<template>
  <div class="flex flex-col h-full bg-surface-canvas"><div v-if="loading" class="flex-1 flex items-center justify-center text-ink-muted">Loading client workspace…</div><div v-else-if="error" class="flex-1 flex items-center justify-center p-6 text-state-danger">{{ error }}</div><template v-else-if="client"><ClientWorkspaceHeader :client="client" @create-document="newDocument"/><ClientWorkspaceTabs :tabs="tabs" v-model:activeTab="activeTab"/><div class="flex-1 overflow-auto p-inline-lg py-stack-lg"><div class="max-w-6xl mx-auto space-y-stack-lg"><div v-if="activeTab==='Overview'" class="space-y-stack-lg"><ClinicalAttentionPanel :client="client"/><div class="grid grid-cols-1 lg:grid-cols-3 gap-stack-lg"><div class="lg:col-span-2 space-y-stack-lg"><section class="bg-surface-elevated border border-border-muted rounded-panel p-inline-lg"><h3 class="text-h3 font-semibold text-ink mb-stack-md pt-stack-md">Recent Sessions</h3><div class="space-y-stack-md pb-stack-md"><div v-for="session in client.recent_sessions||mockClient.recent_sessions" :key="session.id" class="p-inline-md border border-border rounded-control"><div class="flex justify-between"><span class="font-medium">{{ session.type }}</span><span class="text-caption text-ink-muted">{{ session.date }}</span></div><p class="text-body-sm text-ink-secondary mt-1">{{ session.note }}</p></div></div></section><section class="bg-surface-elevated border border-border-muted rounded-panel p-inline-lg"><h3 class="text-h3 font-semibold text-ink mb-stack-md pt-stack-md">Recent Documents</h3><div class="space-y-stack-sm pb-stack-md"><button v-for="doc in documents.slice(0,4)" :key="doc.id" class="w-full text-left p-inline-md border border-border rounded-control" @click="openDocument(doc)"><span class="font-medium">{{ doc.title }}</span><span class="text-caption text-ink-muted block">{{ formatDate(doc.updatedAt) }}</span></button></div></section></div><div class="space-y-stack-lg"><div class="p-inline-md bg-state-warning-surface border border-state-warning/20 rounded-panel"><p class="text-body-sm text-ink-secondary">This workspace still contains some <strong>mock data</strong> outside the document workflow.</p></div></div></div></div><div v-else-if="activeTab==='Details'"><ClientDetails :client="client" @updated="client=$event"/></div><ClientDocumentsPanel v-else-if="activeTab==='Documents'" :documents="documents" :loading="documentsLoading" :error="documentsError" :archived="documentsArchived" @create="newDocument" @edit="editDocument" @view="viewDocument" @download="downloadDocument" @archive="archiveDocument" @restore="restoreDocument" @update:archived="changeArchiveView"/><div v-else><div v-if="activeTab==='Timeline'" class="bg-surface-elevated border border-border-muted rounded-panel p-inline-lg max-w-2xl mx-auto"><h3 class="text-h3 font-semibold text-ink mb-stack-lg pt-stack-md">Client Timeline</h3><TimelineItem v-for="(event,index) in timelineEvents" :key="event.id" :event-type="event.event_type" :date="formatDate(event.occurred_at)" :description="event.summary" :subject-type="event.subject_type" :subject-id="event.subject_id" :session-id="event.session_id" :is-last="index===timelineEvents.length-1"/></div><EmptyState v-else :title="activeTab" :description="`The ${activeTab} module will provide detailed clinical information and management tools for this client's care journey.`" icon="🛠️"/></div></div></div><ClientDocumentComposer v-if="documentComposerOpen" :client="client" :document="editingDocument" @close="closeDocumentComposer" @saved="documentSaved" @show-documents="showDocuments"/><DocumentPreview v-if="previewOpen" :title="previewDocument?.title" :display-url="previewUrl" :loading="previewLoading" :error="previewError" downloadable @close="closePreview" @download="downloadDocument(previewDocument)"/></template></div>
</template>
<script setup>
import { ref,onMounted } from 'vue';import { useRoute } from 'vue-router';import { mockClient } from '../mocks/clientWorkspaceData.js';import { getClient,getTimelineEvents } from '../lib/clients.js';import { downloadClientDocument,listClientDocuments,setClientDocumentArchived,viewClientDocument } from '../lib/clientDocuments.js';import ClientWorkspaceHeader from '../components/workspace/ClientWorkspaceHeader.vue';import ClientWorkspaceTabs from '../components/workspace/ClientWorkspaceTabs.vue';import ClinicalAttentionPanel from '../components/workspace/ClinicalAttentionPanel.vue';import ClientDocumentsPanel from '../components/workspace/ClientDocumentsPanel.vue';import ClientDocumentComposer from '../components/workspace/ClientDocumentComposer.vue';import DocumentPreview from '../components/workspace/DocumentPreview.vue';import TimelineItem from '../components/workspace/TimelineItem.vue';import EmptyState from '../components/workspace/EmptyState.vue';import ClientDetails from './ClientDetails.vue';
const route=useRoute(),client=ref(null),loading=ref(true),error=ref('');const tabs=['Overview','Sessions','Details','Care','Measures','Resources','Documents','Timeline'],activeTab=ref('Overview'),timelineEvents=ref([]);const documents=ref([]),documentsLoading=ref(false),documentsError=ref(''),documentsArchived=ref(false),documentComposerOpen=ref(false),editingDocument=ref(null);const previewOpen=ref(false),previewDocument=ref(null),previewUrl=ref(''),previewLoading=ref(false),previewError=ref('');
async function loadClient(){loading.value=true;try{client.value=await getClient({clientId:route.params.clientId});await Promise.all([loadTimeline(),refreshDocuments()])}catch(e){error.value='The client workspace could not be loaded.'}finally{loading.value=false}}
async function loadTimeline(){try{timelineEvents.value=await getTimelineEvents({clientId:route.params.clientId})}catch{}}
async function refreshDocuments(){documentsLoading.value=true;documentsError.value='';try{documents.value=await listClientDocuments(route.params.clientId,{archived:documentsArchived.value})}catch(e){documentsError.value='Could not load client documents.'}finally{documentsLoading.value=false}}
async function changeArchiveView(value){documentsArchived.value=value;await refreshDocuments()}
function newDocument(){editingDocument.value=null;documentComposerOpen.value=true}function editDocument(d){editingDocument.value=d;documentComposerOpen.value=true}function openDocument(d){d.status==='completed'?viewDocument(d):editDocument(d)}
async function viewDocument(d){previewDocument.value=d;previewOpen.value=true;previewLoading.value=true;previewError.value='';try{previewUrl.value=await viewClientDocument(d)}catch(e){previewError.value=e.message}finally{previewLoading.value=false}}
async function downloadDocument(d){try{await downloadClientDocument(d)}catch(e){documentsError.value='Could not download this document.'}}
async function archiveDocument(d){if(!window.confirm(`Archive “${d.title}”? You can restore it later.`))return;await setClientDocumentArchived(d,true);await refreshDocuments()}async function restoreDocument(d){await setClientDocumentArchived(d,false);await refreshDocuments()}
function closePreview(){previewOpen.value=false;previewDocument.value=null;previewUrl.value=''}function closeDocumentComposer(){documentComposerOpen.value=false;editingDocument.value=null}async function documentSaved(){await refreshDocuments()}function showDocuments(){closeDocumentComposer();activeTab.value='Documents'}function formatDate(v){return v?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):''}onMounted(loadClient);
</script>
